PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY, name TEXT NOT NULL, canonical TEXT NOT NULL UNIQUE, parent_id TEXT REFERENCES topics(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), title TEXT NOT NULL, cwd TEXT, source_path TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_tree(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES conversation_tree(id), topic_id TEXT REFERENCES topics(id), conversation_id TEXT UNIQUE REFERENCES conversations(id), label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS archives(sha256 TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), path TEXT NOT NULL UNIQUE, source_path TEXT NOT NULL, bytes INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), seq INTEGER NOT NULL, role TEXT NOT NULL, timestamp TEXT, content TEXT NOT NULL, source_hash TEXT NOT NULL REFERENCES archives(sha256), source_line INTEGER NOT NULL, UNIQUE(conversation_id,seq));
CREATE TABLE IF NOT EXISTS topic_progress(id TEXT PRIMARY KEY REFERENCES topics(id), version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_items(id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_relations(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES knowledge_items(id), target_id TEXT NOT NULL REFERENCES knowledge_items(id), kind TEXT NOT NULL, version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL, UNIQUE(source_id,target_id,kind));
CREATE TABLE IF NOT EXISTS learning_tasks(id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS updates(id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, actor TEXT NOT NULL, conversation_id TEXT REFERENCES conversations(id), operation TEXT NOT NULL, timestamp TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)));
CREATE TABLE IF NOT EXISTS change_history(id INTEGER PRIMARY KEY AUTOINCREMENT, update_id TEXT NOT NULL REFERENCES updates(id), entity TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT);
CREATE TABLE IF NOT EXISTS sync_state(conversation_id TEXT PRIMARY KEY REFERENCES conversations(id), source_hash TEXT NOT NULL, line_count INTEGER NOT NULL, updated_at TEXT NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS discovery_candidates(conversation_id TEXT PRIMARY KEY, source_path TEXT NOT NULL, reason TEXT NOT NULL, detected_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_messages_conversation_time ON messages(conversation_id,timestamp,seq);
CREATE INDEX IF NOT EXISTS ix_knowledge_topic ON knowledge_items(topic_id,updated_at);
CREATE INDEX IF NOT EXISTS ix_tasks_topic ON learning_tasks(topic_id,updated_at);
CREATE INDEX IF NOT EXISTS ix_rel_target ON knowledge_relations(target_id);
CREATE INDEX IF NOT EXISTS ix_updates_time ON updates(timestamp);
CREATE INDEX IF NOT EXISTS ix_history_entity ON change_history(entity,entity_id,id);
CREATE VIRTUAL TABLE IF NOT EXISTS knowledge_fts USING fts5(id UNINDEXED,text,tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS knowledge_ai AFTER INSERT ON knowledge_items BEGIN INSERT INTO knowledge_fts(id,text) VALUES(new.id,new.data); END;
CREATE TRIGGER IF NOT EXISTS knowledge_au AFTER UPDATE ON knowledge_items BEGIN DELETE FROM knowledge_fts WHERE id=old.id; INSERT INTO knowledge_fts(id,text) VALUES(new.id,new.data); END;
CREATE TRIGGER IF NOT EXISTS knowledge_ad AFTER DELETE ON knowledge_items BEGIN DELETE FROM knowledge_fts WHERE id=old.id; END;
INSERT OR IGNORE INTO conversation_tree(id,parent_id,label) VALUES('root',NULL,'算法竞赛学习');
